#include <iostream>
#include <string_view>

class Notice {
public:
    virtual ~Notice() = default;
    virtual std::string_view text() const = 0;
};

class Welcome final : public Notice {
public:
    std::string_view text() const override { return "Welcome to the library"; }
};

class Reminder final : public Notice {
public:
    std::string_view text() const override { return "Return books on Friday"; }
};

void show(const Notice& notice)
{
    std::cout << notice.text() << '\n';
}

int main()
{
    const Welcome welcome;
    const Reminder reminder;
    show(welcome);
    show(reminder);
}
